package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;public class SharedRateLimiterTest{@Test public void sharedReservationsAndReset(){SharedRateLimiter l=new SharedRateLimiter();assertEquals(1000000000L,l.reserve(0,262144,256));assertEquals(2000000000L,l.reserve(0,262144,256));assertEquals(100000000L,l.reserve(100000000L,262144,0));assertEquals(600000000L,l.reserve(100000000L,262144,512));}}